3	.SYNOPSIS
4	    Read-only: reads requirement records by id through the plugin (getFr, getTr, getTest) and the mappings
5	    that name them (listMappings), printing each record as indented JSON.
6	.PARAMETER Ids
7	    Semicolon-separated requirement ids (FR-, TR-, or TEST-).
8	#>
9	[CmdletBinding()]
10	param(
11	    [Parameter(Mandatory)] [string] $Ids
12	)
13	
14	Set-StrictMode -Version Latest
15	$ErrorActionPreference = 'Stop'
16	. (Join-Path $PSScriptRoot 'CcPlugin.ps1')
17	
18	Write-Output "Now: $((Get-Date).ToString('s'))"
19	$list = @($Ids -split ';' | Where-Object { $_ })
20	foreach ($id in $list) {
21	    $method = switch -Regex ($id) {
22	        '^FR-' { 'workflow.requirements.getFr' }
23	        '^TR-' { 'workflow.requirements.getTr' }
24	        '^TEST-' { 'workflow.requirements.getTest' }
25	        default { throw "Unknown requirement kind: $id" }
26	    }
27	    $r = Invoke-CcPlugin -Method $method -Params ([ordered]@{ id = $id })
28	    $result = Get-CcValue (Get-CcValue $r.Parsed 'payload') 'result'
29	    Write-Output "=== $id ($method exit=$($r.ExitCode))"
30	    if ($null -eq $result) { Write-Output $r.Raw; continue }
31	    $result | ConvertTo-Json -Depth 12
32	}
33	
34	$m = Invoke-CcPlugin -Method 'workflow.requirements.listMappings' -Params ([ordered]@{})
35	$mresult = Get-CcValue (Get-CcValue $m.Parsed 'payload') 'result'
36	$items = @(Get-CcValue $mresult 'items')
37	Write-Output "=== mappings (exit=$($m.ExitCode), $($items.Count) rows) naming the ids"
38	foreach ($row in $items) {
39	    $text = $row | ConvertTo-Json -Depth 8 -Compress
40	    foreach ($id in $list) {
41	        if ($text -match [regex]::Escape('"' + $id + '"')) { Write-Output $text; break }
