#Requires -Version 7.0
<#
.SYNOPSIS
    Converts FRs into their existing TRs through the plugin: appends each FR's acceptance criteria to its TR
    (one criterion restated), records the FR description on the TR, maps the TR and TEST under a parent FR,
    removes the FR's mappings, and deletes the FR. Read-backs gate every destructive step. Supports -WhatIf.
.DESCRIPTION
    Order per conversion: read FR and TR and refuse on any drift from the data file; updateTr; read back and
    prove every FR criterion is on the TR; createMapping under the parent; deleteMapping of the FR's two rows;
    prove the parent mapping survived and the FR has no mappings; deleteFr; prove getFr no longer finds it.
.PARAMETER DataFile
    PowerShell data file with ParentFr and Conversions (FrId, TrId, TestId, ExpectedFrAcs, ExpectedTrAcs,
    PlatformAcIndex, PlatformAcBefore, PlatformAcAfter).
#>
[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Mandatory)] [string] $DataFile
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'CcPlugin.ps1')

function Test-Ok {
    param([Parameter(Mandatory)] $Result)
    return ($Result.ExitCode -eq 0 -and $Result.Raw -notmatch '(?im)^\s*type:\s*error')
}

function Get-Record {
    param([string] $Method, [string] $Id)
    $r = Invoke-CcPlugin -Method $Method -Params ([ordered]@{ id = $Id })
    if (-not (Test-Ok $r)) { return $null }
    return Get-CcValue (Get-CcValue $r.Parsed 'payload') 'result'
}

function Get-MappingRow {
    param([string] $Id)
    $m = Invoke-CcPlugin -Method 'workflow.requirements.listMappings' -Params ([ordered]@{})
    if (-not (Test-Ok $m)) { throw 'listMappings failed' }
    $items = @(Get-CcValue (Get-CcValue (Get-CcValue $m.Parsed 'payload') 'result') 'items')
    return @($items | Where-Object { (($_ | ConvertTo-Json -Depth 8 -Compress) -match [regex]::Escape('"' + $Id + '"')) })
}

function Get-RowKey {
    param($Row)
    return '{0}|{1}|{2}' -f (Get-CcValue $Row 'frId'), (Get-CcValue $Row 'trId'), (Get-CcValue $Row 'testId')
}

function Invoke-Write {
    param([string] $Method, [System.Collections.IDictionary] $Params)
    $r = Invoke-CcPlugin -Method $Method -Params $Params
    Write-Output ('  {0} exit={1} ok={2}' -f $Method, $r.ExitCode, (Test-Ok $r))
    if (-not (Test-Ok $r)) { Write-Output $r.Raw; throw "$Method failed" }
}

$data = Import-PowerShellDataFile -LiteralPath $DataFile
$parent = [string]$data.ParentFr
Write-Output "Now: $((Get-Date).ToString('s')) parent=$parent conversions=$(@($data.Conversions).Count)"
if ($null -eq (Get-Record -Method 'workflow.requirements.getFr' -Id $parent)) { throw "Parent $parent not found" }

foreach ($c in @($data.Conversions)) {
    $frId = [string]$c.FrId; $trId = [string]$c.TrId; $testId = [string]$c.TestId
    Write-Output "=== $frId -> $trId (TEST $testId)"
    $fr = Get-Record -Method 'workflow.requirements.getFr' -Id $frId
    $tr = Get-Record -Method 'workflow.requirements.getTr' -Id $trId
    if ($null -eq $fr -or $null -eq $tr) { throw "Missing $frId or $trId" }
    $frAcs = @(Get-CcValue $fr 'acceptanceCriteria' | Where-Object { $null -ne $_ })
    $trAcs = @(Get-CcValue $tr 'acceptanceCriteria' | Where-Object { $null -ne $_ })
    if ($frAcs.Count -ne [int]$c.ExpectedFrAcs) { throw "$frId has $($frAcs.Count) criteria, expected $($c.ExpectedFrAcs)" }
    if ($trAcs.Count -ne [int]$c.ExpectedTrAcs) { throw "$trId has $($trAcs.Count) criteria, expected $($c.ExpectedTrAcs)" }
    $platformText = [string](Get-CcValue $frAcs[[int]$c.PlatformAcIndex] 'text')
    if ($platformText -ne [string]$c.PlatformAcBefore) { throw "$frId criterion $($c.PlatformAcIndex) drifted: $platformText" }

    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($a in $trAcs) {
        $item = [ordered]@{ id = [string](Get-CcValue $a 'id'); text = [string](Get-CcValue $a 'text'); isSatisfied = [bool](Get-CcValue $a 'isSatisfied') }
        $evidence = Get-CcValue $a 'evidence'
        if ($evidence) { $item.evidence = [string]$evidence }
        $list.Add($item)
    }
    $expectedTexts = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt $frAcs.Count; $i++) {
        $text = if ($i -eq [int]$c.PlatformAcIndex) { [string]$c.PlatformAcAfter } else { [string](Get-CcValue $frAcs[$i] 'text') }
        $id = 'AC-{0:D3}' -f ($trAcs.Count + $i + 1)
        $list.Add([ordered]@{ id = $id; text = $text; isSatisfied = $false })
        $expectedTexts.Add($text)
    }

    $oldDescription = [string](Get-CcValue $tr 'description')
    $coveredOld = "**Covered by:** FR: $frId; TEST: $testId"
    if (-not $oldDescription.Contains($coveredOld)) { throw "$trId description lacks '$coveredOld'" }
    $converted = ('Converted from {0} on 2026-10-19 (operator: "If it is in a FR, then that FR needs to be converted to a TR"; answers "Merge into its TR (Recommended)" and "FR-001, delete FRs (Recommended)"). {0} stated: {1}' -f $frId, [string](Get-CcValue $fr 'description'))
    $newDescription = $oldDescription.Replace($coveredOld, $converted + "`n**Covered by:** FR: $parent; TEST: $testId")
    Write-Output ('  criteria {0} -> {1}; platform criterion becomes {2}' -f $trAcs.Count, $list.Count, $list[$trAcs.Count + [int]$c.PlatformAcIndex].id)
    foreach ($row in $list) { Write-Output ('    {0} {1}' -f $row.id, $(if ($row.text.Length -gt 110) { $row.text.Substring(0, 110) + '...' } else { $row.text })) }

    if (-not $PSCmdlet.ShouldProcess("$frId into $trId", 'updateTr, createMapping, deleteMapping x2, deleteFr')) { continue }

    Invoke-Write -Method 'workflow.requirements.updateTr' -Params ([ordered]@{ id = $trId; description = $newDescription; acceptanceCriteria = @($list) })
    $after = Get-Record -Method 'workflow.requirements.getTr' -Id $trId
    $afterAcs = @(Get-CcValue $after 'acceptanceCriteria' | Where-Object { $null -ne $_ })
    $afterTexts = @($afterAcs | ForEach-Object { [string](Get-CcValue $_ 'text') })
    $missing = @($expectedTexts | Where-Object { $afterTexts -notcontains $_ })
    $descOk = ([string](Get-CcValue $after 'description')).Contains("**Covered by:** FR: $parent; TEST: $testId")
    Write-Output ('  READBACK {0}: criteria={1} missingFrCriteria={2} descriptionRepointed={3}' -f $trId, $afterAcs.Count, $missing.Count, $descOk)
    if ($afterAcs.Count -ne $list.Count -or $missing.Count -gt 0 -or -not $descOk) { throw "Read-back of $trId failed; $frId is not deleted" }

    Invoke-Write -Method 'workflow.requirements.createMapping' -Params ([ordered]@{ frId = $parent; trIds = @($trId); testIds = @($testId); notes = "Converted from $frId on 2026-10-19 by operator decision (IMPL-UNITGREEN-001)." })
    Invoke-Write -Method 'workflow.requirements.deleteMapping' -Params ([ordered]@{ frId = $frId; trId = $trId })
    Invoke-Write -Method 'workflow.requirements.deleteMapping' -Params ([ordered]@{ frId = $frId; testId = $testId })

    $trRows = @(Get-MappingRow -Id $trId | ForEach-Object { Get-RowKey $_ })
    $testRows = @(Get-MappingRow -Id $testId | ForEach-Object { Get-RowKey $_ })
    $frRows = @(Get-MappingRow -Id $frId)
    $parentTr = @($trRows | Where-Object { $_ -like "$parent|$trId|*" }).Count -gt 0
    $parentTest = @($testRows | Where-Object { $_ -like "$parent|*|$testId" }).Count -gt 0
    Write-Output ('  MAPPINGS {0}: [{1}] {2}: [{3}] {4} rows={5}' -f $trId, ($trRows -join '; '), $testId, ($testRows -join '; '), $frId, $frRows.Count)
    if (-not $parentTr -or -not $parentTest -or $frRows.Count -gt 0) { throw "Mapping check failed; $frId is not deleted" }

    Invoke-Write -Method 'workflow.requirements.deleteFr' -Params ([ordered]@{ id = $frId })
